-- A replacement cohort can already have observed a selected-input signal.
-- Finish such jobs with the result transaction, without an empty Queue page.
-- The clock-leading index proves that no older current dependent remains.
CREATE INDEX inventory_matching_selected_dependents_clock ON inventory_matching_selected_dependents(tenant,generation_id,scope_id,facet,record_key,seen_clock);
DROP TRIGGER inventory_matching_selected_job_progress;
CREATE TRIGGER inventory_matching_selected_job_progress BEFORE UPDATE ON inventory_matching_selected_jobs WHEN NEW.work_version=OLD.work_version AND (NEW.completed_version,NEW.cursor_destination,NEW.cursor_source,NEW.cursor_clock,NEW.cursor_set,NEW.last_turn) IS NOT (OLD.completed_version,OLD.cursor_destination,OLD.cursor_source,OLD.cursor_clock,OLD.cursor_set,OLD.last_turn) AND NOT(NEW.completed_version=OLD.work_version AND OLD.completed_version<OLD.work_version AND (NEW.cursor_destination,NEW.cursor_source,NEW.cursor_clock,NEW.cursor_set,NEW.last_turn)=(OLD.cursor_destination,OLD.cursor_source,OLD.cursor_clock,OLD.cursor_set,OLD.last_turn) AND NOT EXISTS(SELECT 1 FROM inventory_matching_selected_dependents d INDEXED BY inventory_matching_selected_dependents_clock WHERE d.tenant=OLD.tenant AND d.generation_id=OLD.generation_id AND d.scope_id=OLD.scope_id AND d.facet=OLD.facet AND d.record_key=OLD.record_key AND d.seen_clock<OLD.work_version)) BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM inventory_matching_selected_pages p INDEXED BY inventory_matching_selected_page_prepared JOIN inventory_matching_selected_guards g ON g.tenant=p.tenant AND g.page_id=p.page_id WHERE p.tenant=OLD.tenant AND p.generation_id=OLD.generation_id AND p.scope_id=OLD.scope_id AND p.facet=OLD.facet AND p.record_key=OLD.record_key AND p.work_version=OLD.work_version AND p.completed_version=OLD.completed_version AND p.previous_turn=OLD.last_turn AND p.next_turn=NEW.last_turn AND (p.previous_destination,p.previous_source,p.previous_clock,p.previous_set)=(OLD.cursor_destination,OLD.cursor_source,OLD.cursor_clock,OLD.cursor_set) AND (p.next_destination,p.next_source,p.next_clock,p.next_set)=(NEW.cursor_destination,NEW.cursor_source,NEW.cursor_clock,NEW.cursor_set) AND NEW.completed_version=CASE p.complete WHEN 1 THEN p.work_version ELSE p.completed_version END AND p.state='prepared' AND NOT EXISTS(SELECT 1 FROM inventory_matching_selected_page_stale x WHERE x.tenant=p.tenant AND x.page_id=p.page_id)) THEN RAISE(ABORT,'inventory matching selected progress guard missing') END;
END;
CREATE TRIGGER inventory_matching_selected_observed AFTER UPDATE OF state ON inventory_match_sets WHEN OLD.state='prepared' AND NEW.state='committed' BEGIN
 UPDATE inventory_matching_selected_jobs SET completed_version=work_version
 WHERE rowid IN(SELECT j.rowid FROM inventory_match_rows q CROSS JOIN inventory_matching_selected_jobs j
 WHERE q.tenant=NEW.tenant AND q.set_id=NEW.set_id AND j.tenant=q.tenant AND j.generation_id=NEW.generation_id AND j.scope_id=q.source_scope AND j.facet='source' AND j.record_key=q.record_key AND j.completed_version<j.work_version
 AND NOT EXISTS(SELECT 1 FROM inventory_matching_selected_dependents d INDEXED BY inventory_matching_selected_dependents_clock WHERE d.tenant=j.tenant AND d.generation_id=j.generation_id AND d.scope_id=j.scope_id AND d.facet=j.facet AND d.record_key=j.record_key AND d.seen_clock<j.work_version));
END;
